[
  {
    "question": "Which of the following best defines a domain in the relational model?",
    "options": {
      "A": "A set of tuples that satisfy a relation schema",
      "B": "The allowed set of atomic values for an attribute",
      "C": "A collection of tables that share a common primary key",
      "D": "A temporary view created by a sub‑query"
    },
    "correct_answer": "B",
    "explanation": "A domain is the set of permissible atomic values that an attribute can take, as stated in the notes.",
    "difficulty": "Medium"
  },
  {
    "question": "In a relational schema, which statement is true regarding candidate keys and the primary key?",
    "options": {
      "A": "Every candidate key must be declared as a primary key",
      "B": "A primary key can contain NULL values, but candidate keys cannot",
      "C": "All candidate keys are minimal superkeys, and one of them is chosen as the primary key",
      "D": "A primary key is always a composite key, while candidate keys are always single‑attribute"
    },
    "correct_answer": "C",
    "explanation": "Candidate keys are minimal superkeys; one of them is selected as the primary key, while the others remain alternate keys.",
    "difficulty": "Medium"
  },
  {
    "question": "Which of the following lists the three main steps used to compute a minimal cover of a set of functional dependencies?",
    "options": {
      "A": "Decompose relations, enforce referential integrity, create indexes",
      "B": "Split right‑hand sides, remove extraneous attributes, delete redundant dependencies",
      "C": "Apply Armstrong’s axioms, compute closure, identify superkeys",
      "D": "Normalize to 3NF, add check constraints, define triggers"
    },
    "correct_answer": "B",
    "explanation": "The minimal‑cover procedure consists of (1) splitting RHS to single attributes, (2) removing extraneous attributes from LHS, and (3) eliminating redundant dependencies.",
    "difficulty": "Medium"
  },
  {
    "question": "Why can the HAVING clause use COUNT(*) while the WHERE clause cannot?",
    "options": {
      "A": "HAVING is evaluated after grouping, so COUNT(*) has a defined value; WHERE is evaluated before grouping",
      "B": "WHERE can only reference columns from a single table, while HAVING can reference any table",
      "C": "COUNT(*) returns NULL in HAVING, which is treated as FALSE in WHERE",
      "D": "WHERE automatically removes duplicate rows, making COUNT unnecessary"
    },
    "correct_answer": "A",
    "explanation": "HAVING operates on grouped results, where aggregate functions like COUNT(*) are defined; WHERE works on raw rows before aggregation, so COUNT(*) is not allowed there.",
    "difficulty": "Medium"
  },
  {
    "question": "Which join operation returns all rows from the left input relation and fills unmatched right‑side attributes with NULL?",
    "options": {
      "A": "INNER JOIN",
      "B": "RIGHT OUTER JOIN",
      "C": "FULL OUTER JOIN",
      "D": "LEFT OUTER JOIN"
    },
    "correct_answer": "D",
    "explanation": "A LEFT OUTER JOIN keeps every row from the left relation and inserts NULLs for columns of the right relation when there is no match.",
    "difficulty": "Medium"
  }
]
